#pragma once
// Included by BridgeCpuTests after its GL mocks and packet helpers.
void testPostProcess(){
    const auto rejects=[](auto action){try{action();}catch(const std::runtime_error&){return true;}return false;};
    const glm::vec4 fog(.2f,.3f,.4f,1);
    bridge::ColorBufferSpec color;color.index=0;color.format=GL_RGBA16F;
    auto persistent=color;persistent.index=1;persistent.clearEachFrame=false;
    auto sparse=color;sparse.index=31;sparse.clearEachFrame=false;sparse.mipmaps=true;
    bridge::PostProcess post;const auto allocatedBefore=mock::textureAllocations;
    post.configure({color,persistent,sparse},64,32,64ull*32*60);
    requireCPU(mock::textureAllocations==allocatedBefore+6&&post.bytes==64ull*32*8*4+(64ull*32+32*16+16*8+8*4+4*2+2+1)*8*2,"Postprocess allocation omitted paired storage or exact mip chain bytes.");
    const auto clearStart=mock::colorClears.size();post.begin(fog);
    requireCPU(mock::colorClears.size()==clearStart+6,"New persistent buffers were not initialized on both sides.");
    requireCPU(mock::colorClears[clearStart].value==glm::dvec4(fog)&&mock::colorClears[clearStart+2].value==glm::dvec4(1)&&mock::colorClears[clearStart+4].value==glm::dvec4(0),"Default fog/one/zero clear semantics differ.");
    const auto first=post.current(31),alternate=post.alternate(31),one=post.current(1);
    bridge::FullscreenPass pass{20001,20002,{{1,3,31,0,false}},{{31,true},{1,false}}};
    const auto beforeDraw=mock::fullscreenDraws.size();post.run(pass);
    const auto& draw=mock::fullscreenDraws.at(beforeDraw);
    requireCPU(draw.input==first&&draw.outputs==std::vector<GLuint>{alternate,post.alternate(1)}&&draw.width==64&&draw.height==32,"Sparse logical IDs were used as physical attachments, or the pass reads/writes the same side.");
    requireCPU(post.current(31)==alternate&&post.current(1)==one,"Disabled flip changed the sampler side.");
    requireCPU(mock::framebufferTextures.at(post.targetFramebuffer()).at(GL_COLOR_ATTACHMENT0)==alternate,"Output location zero did not route to logical buffer 31.");
    pass.outputs={{31,true}};post.run(pass);
    requireCPU(post.current(31)==first&&mock::framebufferTextures.at(post.targetFramebuffer()).at(GL_COLOR_ATTACHMENT1)==0,"Following pass kept stale attachments or lost ping-pong state.");
    const auto mipStart=mock::mipmapTextures.size();pass.inputs[0].mipmaps=true;pass.outputs={{1,true}};post.run(pass);post.run(pass);
    requireCPU(mock::mipmapTextures.size()==mipStart+1&&mock::mipmapTextures.back()==first,"Unchanged mip input regenerated its chain or used the wrong ping-pong side.");
    pass.outputs={{31,true}};post.run(pass);post.run(pass);
    requireCPU(mock::mipmapTextures.size()==mipStart+2,"Written alternate texture reused a stale mip chain.");
    post.complete();const auto stableMain=post.current(31);const auto stableStamp=mock::images.at(stableMain).stamp;
    const auto queries=mock::integerQueries,allocations=mock::textureAllocations;const auto nextClear=mock::colorClears.size();
    post.configure({color,persistent,sparse},64,32,64ull*32*60);post.begin(fog);
    requireCPU(mock::integerQueries==queries&&mock::textureAllocations==allocations&&mock::colorClears.size()==nextClear+2&&post.current(31)==stableMain&&mock::images.at(stableMain).stamp==stableStamp,"Stable buffers queried/reallocated or cleared persistent contents.");
    pass.inputs[0].mipmaps=false;pass.outputs={{31,true}};const auto beforeFailure=post.current(31);mock::failComposite=true;
    requireCPU(rejects([&]{post.run(pass);})&&post.current(31)==beforeFailure,"Failed fullscreen draw flipped its targets.");
    requireCPU(rejects([&]{post.run(pass);}),"Failed postprocess frame remained executable.");
    const auto recoveryClear=mock::colorClears.size();post.begin(fog);
    requireCPU(mock::colorClears.size()==recoveryClear+6,"Failed frame did not reset persistent scratch buffers.");
    const auto draws=mock::fullscreenDraws.size();
    auto bad=pass;bad.outputs={{31,true},{31,false}};
    requireCPU(rejects([&]{post.run(bad);}),"Duplicate logical outputs were accepted.");
    bad=pass;bad.inputs[0].logical=-1;bad.inputs[0].external=post.alternate(31);
    requireCPU(rejects([&]{post.run(bad);}),"Explicit framebuffer texture feedback was accepted.");
    bad=pass;bad.inputs.push_back(bad.inputs[0]);
    requireCPU(rejects([&]{post.run(bad);}),"Two input samplers aliased a texture unit.");
    bad=pass;bad.inputs[0].unit=16;
    requireCPU(rejects([&]{post.run(bad);}),"Fragment texture-unit limit was ignored.");
    bad=pass;bad.inputs[0].logical=30;
    requireCPU(rejects([&]{post.run(bad);}),"Missing logical input was silently substituted.");
    bad=pass;bad.inputs.push_back({2,4,31,0,true});
    requireCPU(rejects([&]{post.run(bad);}),"Conflicting per-texture mip policies were accepted.");
    bad=pass;bad.inputs[0].logical=0;bad.inputs[0].mipmaps=true;
    requireCPU(rejects([&]{post.run(bad);})&&mock::fullscreenDraws.size()==draws,"Unreserved mips or invalid pass validation performed a draw.");
    post.complete();const auto oldFramebuffer=post.targetFramebuffer(),oldColor=post.current(31);const auto deleted=mock::deletedTextures.size();
    mock::framebufferChecksBeforeFailure=2;
    requireCPU(rejects([&]{post.configure({color,persistent,sparse},128,64,128ull*64*60);})&&post.targetFramebuffer()==oldFramebuffer&&post.current(31)==oldColor&&mock::deletedTextures.size()==deleted+3,"Partial postprocess allocation leaked textures or replaced working storage.");
    auto invalid=color;invalid.index=32;
    requireCPU(rejects([&]{post.configure({invalid},64,32,0);}),"Logical color index 32 was accepted.");
    invalid=color;invalid.scaleX=std::numeric_limits<double>::infinity();
    requireCPU(rejects([&]{post.configure({invalid},64,32,0);}),"Nonfinite relative buffer size was accepted.");
    invalid=color;invalid.scaleX=.001;
    requireCPU(rejects([&]{post.configure({invalid},64,32,0);}),"Zero-rounded relative buffer size was accepted.");
    invalid=color;invalid.format=GL_DEPTH_COMPONENT32F;
    requireCPU(rejects([&]{post.configure({invalid},64,32,0);}),"A depth format was accepted as a color buffer.");
    invalid=color;invalid.clear.x=std::numeric_limits<float>::quiet_NaN();
    requireCPU(rejects([&]{post.configure({invalid},64,32,0);}),"Nonfinite buffer clear was accepted.");
    requireCPU(rejects([&]{post.configure({color,color},64,32,0);}),"Repeated color descriptors were accepted.");
    requireCPU(rejects([&]{post.configure({color},3840,2160,3840ull*2160*60);})&&post.current(31)==oldColor,"Combined geometry/postprocess budget was exceeded.");
    auto narrow=color;narrow.fixedWidth=7;narrow.fixedHeight=3;narrow.mipmaps=true;narrow.format=GL_RGBA8;
    requireCPU(bridge::PostProcess::estimate({narrow},100,100)==200,"Odd/rectangular mip sizes were rounded incorrectly.");
    const auto released=mock::deletedTextures.size();post.configure({},64,32,64ull*32*60);
    requireCPU(post.bytes==0&&post.targetFramebuffer()==0&&mock::deletedTextures.size()==released+6,"Unused postprocess buffers were not fully released.");
    {
        bridge::PostProcess typed;auto signedBuffer=color;signedBuffer.index=7;signedBuffer.format=GL_RGBA32I;signedBuffer.customClear=true;signedBuffer.clear={-7,2,3,4};
        auto unsignedBuffer=signedBuffer;unsignedBuffer.index=13;unsignedBuffer.format=GL_RGBA32UI;unsignedBuffer.clear={11,12,13,14};
        typed.configure({signedBuffer,unsignedBuffer},16,8,0);const auto start=mock::colorClears.size();typed.begin(fog);
        requireCPU(mock::colorClears[start].kind==GL_INT&&mock::colorClears[start].value.x==-7&&mock::colorClears[start+2].kind==GL_UNSIGNED_INT&&mock::colorClears[start+2].value.x==11,"Integer clear used float conversion instead of typed GL clear.");typed.complete();
        signedBuffer.linear=true;requireCPU(rejects([&]{typed.configure({signedBuffer},16,8,0);}),"Integer color buffer used linear filtering.");
        unsignedBuffer.clear.x=-1;requireCPU(rejects([&]{typed.configure({unsignedBuffer},16,8,0);}),"Negative unsigned clear color was accepted.");
        signedBuffer.linear=false;signedBuffer.clear.x=2147483648.f;requireCPU(rejects([&]{typed.configure({signedBuffer},16,8,0);}),"Out-of-range signed clear was converted with undefined behavior.");
    }
    {
        bridge::PostProcess dimensions;auto half=color;half.index=2;half.scaleX=half.scaleY=.5;
        std::vector<bridge::ColorBufferSpec> specs={color,half};for(uint32_t i=3;i<11;++i){auto extra=color;extra.index=i;specs.push_back(extra);}dimensions.configure(specs,64,32,0);dimensions.begin(fog);
        bridge::FullscreenPass mixed{20001,20002,{{1,3,0,0,false}},{{0,true},{2,true}}};
        requireCPU(rejects([&]{dimensions.run(mixed);}),"Differently sized outputs shared a fullscreen framebuffer.");
        mixed.outputs={{2,true}};dimensions.run(mixed);requireCPU(mock::fullscreenDraws.back().width==32&&mock::fullscreenDraws.back().height==16,"Relative target viewport was not used.");
        mixed.outputs.clear();for(uint32_t i=3;i<12;++i)mixed.outputs.push_back({i,true});
        requireCPU(rejects([&]{dimensions.run(mixed);}),"More than GPU max draw buffers were accepted.");dimensions.complete();
    }
    {
        bridge::Renderer renderer;renderer.initialize();Payload start;start.words({91});renderer.receive(bridge::Reset,0,start.bytes);
        Payload camera;camera.words({91,0,640,360});camera.matrix(glm::mat4(1));camera.matrix(glm::mat4(1));camera.floats({0,0,0,.1f,.2f,.3f,1});renderer.receive(bridge::Camera,1,camera.bytes);
        Payload ready;ready.words({91,1,1});renderer.receive(bridge::RenderControl,2,ready.bytes);
        const auto defaultTextures=mock::textureAllocations,defaultDraws=mock::composites;renderer.render(0,640,360,false);
        requireCPU(mock::textureAllocations==defaultTextures+8&&mock::composites==defaultDraws&&!renderer.targets.history.allocated()&&renderer.postprocess.bytes==0,"Default embedded path allocated unrequested post/history targets or executed extra fullscreen draws.");
        const auto defaultQueries=mock::integerQueries;renderer.render(0,640,360,false);
        requireCPU(mock::integerQueries==defaultQueries&&mock::textureAllocations==defaultTextures+8&&mock::composites==defaultDraws,"Stable default embedded path performed new queries, allocations or fullscreen passes.");
        auto spec=color;spec.index=31;renderer.postBufferSpecs={spec};renderer.finalBuffer=31;
        bridge::FullscreenPass effect{20001,renderer.compositeVAO,{{1,3,-1,0,false,bridge::PassTexture::Scene},{2,4,-1,0,false,bridge::PassTexture::PreviousColor}},{{31,true}},99};renderer.postPasses={effect};
        const auto drawStart=mock::fullscreenDraws.size();renderer.render(0,640,360,false);
        requireCPU(renderer.targets.history.allocated()&&!renderer.previousWorld.valid&&mock::fullscreenDraws.size()==drawStart+2,"Embedded post chain did not enable demanded history or resolve its result.");
        const auto firstResult=mock::fullscreenDraws[drawStart];const auto resolve=mock::fullscreenDraws[drawStart+1];
        requireCPU(firstResult.input==renderer.targets.colors[0]&&firstResult.outputs==std::vector<GLuint>{renderer.postprocess.current(31)}&&resolve.input==renderer.postprocess.current(31)&&resolve.framebuffer==renderer.targets.framebuffer&&resolve.outputs==std::vector<GLuint>{renderer.targets.colors[0]},"Embedded final bypassed the actual effect result or overwrote opaque geometry metadata.");
        requireCPU(mock::bound[GL_TEXTURE4]==renderer.fallbackPlain,"Unavailable prior color did not bind a complete neutral texture.");
        const auto completedCamera=renderer.cameraFrame.counter;renderer.render(0,640,360,false);
        requireCPU(renderer.previousWorld.valid&&mock::bound[GL_TEXTURE4]==renderer.previousWorld.color&&renderer.cameraFrame.counter==completedCamera+1,"Post chain did not bind the matching completed world history.");
        const auto committed=renderer.targets.history.commits;mock::failComposite=true;
        requireCPU(rejects([&]{renderer.render(0,640,360,false);})&&renderer.targets.history.commits==committed,"Failed post chain committed temporal world history.");
        mock::fullscreenDrawsBeforeFailure=1;
        requireCPU(rejects([&]{renderer.render(0,640,360,false);})&&renderer.targets.history.commits==committed,"Failed final resolve committed temporal world history.");
        renderer.render(0,800,450,false);requireCPU(!renderer.previousWorld.valid&&mock::fullscreenDraws.back().width==800&&renderer.postPasses[0].inputs[0].external==renderer.targets.colors[0],"Resize retained stale effect/history texture handles.");
        renderer.invalidateHistory();const auto clearCount=mock::colorClears.size();renderer.render(0,800,450,false);
        requireCPU(mock::colorClears.size()>=clearCount+2&&!renderer.previousWorld.valid,"Fallback did not invalidate effect resources/history.");
        renderer.postPasses.clear();renderer.postBufferSpecs.clear();renderer.finalBuffer=-1;const auto releasedCount=mock::deletedTextures.size();renderer.render(0,800,450,false);
        requireCPU(!renderer.targets.history.allocated()&&renderer.postprocess.bytes==0&&mock::deletedTextures.size()==releasedCount+6,"Disabled post chain retained undemanded buffers/history.");
        renderer.postBufferSpecs={spec};renderer.postPasses={effect};renderer.postPasses[0].historyValid=-1;
        requireCPU(rejects([&]{renderer.render(0,800,450,false);}),"Temporal effect sampled unavailable history without a validity contract.");
        renderer.postPasses.clear();renderer.postBufferSpecs[0].format=GL_RGBA32UI;renderer.finalBuffer=31;
        requireCPU(rejects([&]{renderer.render(0,800,450,false);}),"Built-in floating final sampler accepted an integer render target.");
    }
}
